#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto doop=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };
    for(int t=0;t<n;t++){
        int pos=-1;
        for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
        if(pos==t) continue;
        // Move element from pos to position t
        // Step 1: move to position 0
        if(pos>0 && pos<n-1){
            // x=pos, y=1: result=[p[n-1], p[pos..n-2], p[0..pos-1]]. Element at pos goes to index 1. Not helpful.
            // x=1, y=n-1-pos: suffix=p[pos+1..n-1], middle=p[1..pos], prefix=p[0]. Element at pos -> index n-1-pos+(pos-1)=n-2. 
            // Bring to front: x=pos, y=n-pos: but x+y=n, invalid.
            // x=pos, y=n-pos-1: suffix=p[pos+1..n-1], middle=p[pos], prefix=p[0..pos-1]. 
            // Element at pos is in middle at output index (n-pos-1). 
            doop(pos, n-pos-1); // element now at n-pos-1
            pos=n-pos-1;
        }
        if(pos==t) continue;
        // Now pos is 0 or n-1
        if(pos==0 && t>0 && t<n-1){
            doop(t, n-1-t); // suffix=p[t+1..n-1], middle=p[t], prefix=p[0..t-1]. Element at 0 goes to end: n-1. But wait, 0 is in prefix.
            // prefix=p[0..t-1], element at 0 is in prefix, goes to output index (n-1-t)+(t)+ ... = n-t + ... 
            // Output: [p[n-1-n+1+t..n-1], p[t..n-1-n+1+t-1], p[0..t-1]] = [p[t+1..n-1], p[t], p[0..t-1]]
            // p[0] at output index n-1. 
            pos=n-1;
        }
        if(pos==t) continue;
        if(pos==n-1 && t<n-1){
            int y=n-1-t; if(t+1>0&&y>0&&t+1+y<n) doop(t+1,y);
            // Check
        } else if(pos>0 && t==0){
            if(pos<n-1) doop(1,n-1-pos);
            for(int i=0;i<n;i++) if(p[i]==t+1){pos=i;break;}
            if(pos!=0 && pos==n-1) doop(1,1);
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
